// Extraer datos del evento de Evolution API
const body = $input.first().json.body || $input.first().json;

// Estructura del evento Evolution API
const event = body.event || '';
const data = body.data || {};

// Solo procesar mensajes recibidos (no los enviados por nosotros)
if (event !== 'messages.upsert' && event !== 'MESSAGES_UPSERT') {
  throw new Error(`Evento ignorado: ${event}`);
}

const message = data.message || {};
const key = data.key || {};

// Ignorar mensajes propios
if (key.fromMe === true) {
  throw new Error('Mensaje propio ignorado');
}

// Ignorar mensajes de grupo
if (key.remoteJid && key.remoteJid.includes('@g.us')) {
  throw new Error('Mensaje de grupo ignorado');
}

// Extraer numero de telefono (formato: 573001234567@s.whatsapp.net)
const jid = key.remoteJid || '';
const phone = jid.replace('@s.whatsapp.net', '').replace('@c.us', '');

// Extraer texto del mensaje
const text = message.conversation || 
             message.extendedTextMessage?.text || 
             message.imageMessage?.caption || 
             '';

if (!phone || !text) {
  throw new Error('No se pudo extraer telefono o texto del mensaje');
}

console.log(`Mensaje recibido de ${phone}: "${text}"`);

return [{
  json: {
    phone: phone,
    phone_normalized: phone.replace(/[^0-9]/g, ''),
    text: text,
    text_lower: text.toLowerCase(),
    received_at: new Date().toISOString()
  }
}];

// Analizar la respuesta del prospecto
// Detectar si indica proceso manual o interes
const text = $json.text_lower || '';

// Keywords positivos - indican que hacen proceso MANUAL o tienen INTERES
const positiveKeywords = [
  'manual', 'a mano', 'no tenemos', 'no lo hacemos', 'todavia', 'todavía',
  'no', 'negativo', 'no automatico', 'no automatizado', 'por llamada',
  'por telefono', 'llamamos', 'whatsapp manual', 'nosotros mismos',
  'si', 'sí', 'claro', 'como', 'cómo', 'interesa', 'interesado',
  'quiero', 'cuéntame', 'cuentame', 'hablame', 'háblame', 'que es',
  'qué es', 'como funciona', 'cómo funciona', 'mas info', 'más info',
  'que hace', 'qué hace', 'explicame', 'explícame'
];

// Keywords negativos - no interesados
const negativeKeywords = [
  'no gracias', 'no me interesa', 'no interesa', 'ya tenemos', 
  'ya contamos', 'ya usamos', 'no necesitamos', 'no necesito',
  'quitar', 'borrar', 'stop', 'baja', 'spam'
];

const isNegative = negativeKeywords.some(kw => text.includes(kw));
const isPositive = positiveKeywords.some(kw => text.includes(kw));

// Cualquier respuesta que no sea negativa = oportunidad
const shouldProceed = !isNegative && (isPositive || text.length > 0);

return [{
  json: {
    ...$json,
    is_positive: isPositive,
    is_negative: isNegative,
    should_proceed: shouldProceed,
    keyword_matched: positiveKeywords.find(kw => text.includes(kw)) || null
  }
}];

// Delay humanizado antes de responder: 2-5 minutos
// Simula que una persona real leyó y respondió
const min = 2 * 60 * 1000;  // 2 min
const max = 5 * 60 * 1000;  // 5 min
const delay = Math.floor(Math.random() * (max - min + 1)) + min;

console.log(`Esperando ${delay/60000} minutos antes de enviar Mensaje 2...`);
await new Promise(resolve => setTimeout(resolve, delay));

return $input.all();

// Construir Mensaje 2 - Propuesta de Valor
const item = $input.first().json;
const name = item.name || '';

// Variaciones para evitar deteccion de template repetitivo
const intros = [
  'Te pregunto porque',
  'Te cuento que',
  'Te comento que'
];
const introIdx = Math.floor(Math.random() * intros.length);

const mensaje = `${intros[introIdx]} a varios colegas en el sector les pasaba que perdían clientes que se iban a la competencia por olvido. Nosotros ayudamos a más de 30 talleres en Colombia a automatizar eso con sus propios números de WhatsApp. ¿Te gustaría ver cómo se ve un mensaje de recordatorio automático?`;

return [{
  json: {
    ...item,
    mensaje_m2: mensaje
  }
}];
